package dev.basefinder.core;

/**
 * Maps a block id to a {@link Cat}. This is a heuristic: a block id cannot tell us whether a stone block was
 * placed by a player or generated by the world, so "BUILT" means "block types players typically build with".
 */
public final class BlockKinds {
    private BlockKinds() {}

    private static boolean has(String id, String... parts) {
        for (String p : parts) if (id.contains(p)) return true;
        return false;
    }

    public static Cat classify(String fullId) {
        String id = fullId.startsWith("minecraft:") ? fullId.substring(10) : fullId;

        switch (id) {
            case "air", "cave_air", "void_air": return Cat.AIR;
            case "water", "bubble_column", "kelp", "kelp_plant", "seagrass", "tall_seagrass": return Cat.WATER;
            case "lava": return Cat.LAVA;
            case "fire", "soul_fire": return Cat.FIRE;
            case "tnt": return Cat.TNT;
            case "respawn_anchor": return Cat.ANCHOR;
            case "obsidian", "crying_obsidian": return Cat.OBSIDIAN;
            case "nether_portal", "end_portal", "end_gateway", "end_portal_frame": return Cat.PORTAL;
            case "ender_chest", "campfire", "soul_campfire", "crafting_table", "smithing_table", "fletching_table",
                 "cartography_table", "loom", "stonecutter", "grindstone", "anvil", "chipped_anvil", "damaged_anvil",
                 "enchanting_table", "brewing_stand", "cauldron", "water_cauldron", "lava_cauldron", "beacon", "conduit",
                 "hopper", "dropper", "dispenser", "crafter", "observer", "piston", "sticky_piston", "comparator",
                 "repeater", "lectern", "jukebox", "note_block", "bell", "lodestone", "respawn_station":
                return Cat.INFRA;
            case "chest", "trapped_chest": return Cat.CHEST;
            case "barrel": return Cat.BARREL;
            case "farmland", "composter", "hay_block", "melon", "pumpkin": return Cat.FARMLAND;
            case "snow", "cobweb", "bamboo", "bamboo_sapling", "cactus", "short_grass", "tall_grass", "fern",
                 "large_fern", "dead_bush", "vine", "red_mushroom", "brown_mushroom", "glow_lichen", "sculk_vein",
                 "pointed_dripstone", "bush", "leaf_litter", "wildflowers", "firefly_bush", "short_dry_grass",
                 "tall_dry_grass", "sea_pickle", "dripstone_pointed":
                return Cat.PLANT;
            case "wheat", "carrots", "potatoes", "beetroots", "nether_wart", "sugar_cane", "sweet_berry_bush", "cocoa",
                 "melon_stem", "pumpkin_stem", "attached_melon_stem", "attached_pumpkin_stem", "torchflower_crop",
                 "pitcher_crop":
                return Cat.CROP;
            default:
                break;
        }

        if (id.endsWith("shulker_box")) return Cat.SHULKER;
        if (id.endsWith("_bed")) return Cat.BED;
        if (has(id, "furnace", "smoker")) return Cat.INFRA;
        if (id.endsWith("_door") || id.endsWith("trapdoor") || id.endsWith("fence_gate")) return Cat.DOOR;
        if (has(id, "glass") || id.endsWith("iron_bars") || id.endsWith("_bars")) return Cat.GLASS;
        if (has(id, "torch", "lantern", "candle", "end_rod")) return Cat.LIGHT;
        if (has(id, "carpet", "_sign", "banner", "button", "lever", "pressure_plate", "rail", "ladder", "tripwire",
                "flower_pot", "_head", "_skull", "redstone_wire", "scaffolding", "item_frame", "painting", "chain")) {
            return id.contains("moss_carpet") ? Cat.PLANT : Cat.DECOR;
        }
        if (has(id, "flower", "tulip", "orchid", "allium", "poppy", "dandelion", "cornflower", "lily", "rose_bush", "peony",
                "lilac", "sapling", "propagule", "azalea", "roots", "spore_blossom", "pitcher_plant", "torchflower",
                "eyeblossom", "coral_fan", "coral_wall_fan", "_coral", "lichen", "vines", "moss_carpet")
                && !has(id, "_block", "planks", "leaves", "_stairs", "_slab")) {
            return Cat.PLANT;
        }
        if (id.contains("grass") && !id.contains("grass_block")) return Cat.PLANT;

        // Blocks players typically build with.
        if (has(id, "planks", "brick", "concrete", "wool", "terracotta", "_slab", "_stairs", "fence", "polished", "smooth_",
                "cut_", "chiseled", "quartz", "prismarine", "purpur", "copper", "bookshelf", "glowstone", "sea_lantern",
                "tiles", "_wall", "cobblestone", "stripped_", "mud_brick", "resin", "froglight", "bamboo_mosaic", "_planks")
                && !has(id, "wall_torch", "wall_sign", "wall_banner", "wall_hanging", "wall_head", "wall_skull", "wall_fan")) {
            return Cat.BUILT;
        }
        if (id.endsWith("_block") && !has(id, "grass_block", "moss_block", "bone_block", "magma_block", "raw_", "slime", "honey",
                "mushroom_block", "amethyst_block", "budding", "sculk", "dried_kelp", "packed_ice", "blue_ice")) {
            return Cat.BUILT;
        }
        return Cat.NATURAL;
    }
}
